UPDATE kouzla SET rozsah = '1 objekt', popis = 'Původní/magické jméno: gray. Kouzelník vytvoří objekt spojený se zemí, může se jednat o cokoliv si čaroděj dokáže představit. Může se jednat o ledovou sochu konkrétní osoby, dům, katapult. Objekt je pevně spojen se zemí a nemůže se nijak pohybovat, pokus o jeho přemístění ho zničí. Objekt má 10 životů a obranu 1.' WHERE id = 176 AND nazev = 'Ledová tvorba-objekt';
UPDATE kouzla SET rozsah = '1 bytost max C', popis = 'Uvězní jednu bytost v ledovém sloupu tato bytost ztrácí iniciativu na 1k6 kol, po kterých se sice nemůže jakkoliv hýbat nebo bránit, ale má KZ 20 Cryomancer se může rozhodnout zdali na bytost uplatní své bonusy za mráz či nikoliv' WHERE id = 177 AND nazev = 'Ledové vězení';
