UPDATE kouzla SET rozsah = '1 cíl', popis = 'Cíl pod vlivem kouzla získá +4 ke stupni síly včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' WHERE id = 484 AND nazev = 'Slovo síly IV';
