UPDATE kouzla SET rozsah = '1 cíl', popis = 'Cíl pod vlivem kouzla získá ochranný štít v hodnotě 20 % maximálních životů cíle. Tento štít pohltí veškeré zdroje zranění a ubývá jako první.' WHERE id = 486 AND nazev = 'Slovo ochrany II';
