UPDATE kouzla SET rozsah = '1 cíl', popis = 'Cíl pod vlivem kouzla získá +2 ke stupni obratnosti včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' WHERE id = 489 AND nazev = 'Slovo rychlosti II';
