UPDATE kouzla SET rozsah = '1 cíl', popis = 'Působení: Musí umět Runa Lékárníka I. Cíl nemusí souhlasit s efektem kouzla. Pokud nesouhlasí hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce.Cíl který neuspěl v hodu proti pasti, obdrží bonusové léčení stejné povahy jakým byl samotný zdroj. Velikost bonusu je 1k6+2.' WHERE id = 556 AND nazev = 'Runa Lékárníka II';
UPDATE kouzla SET rozsah = '1 cíl', popis = 'Působení: Musí umět Runa Lékárníka II. Cíl nemusí souhlasit s efektem kouzla. Pokud nesouhlasí hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce.Cíl který neuspěl v hodu proti pasti, obdrží bonusové léčení stejné povahy jakým byl samotný zdroj. Velikost bonusu je 1k8+3.' WHERE id = 557 AND nazev = 'Runa Lékárníka III';
