UPDATE kouzla SET rozsah = 'novic', popis = 'Únava: 4 body. Četnost: max 5x za den. Zátěž z naložení nesmí přesáhnout 1 500 mincí. Postava nemůže volně létat. Pokud odněkud spadne, snáší se k zemi rychlostí 1 sáh za kolo.' WHERE id = 730 AND nazev = 'Levitace';
UPDATE kouzla SET rozsah = '1 tvor', popis = 'Únava: 1 bod za každé 2 případné magy. Pomocí tohoto kouzla je možné odstranit účinky psychických kouzel. Základní šance že bude kouzlo úspěšné je 65% +5% za každou úroveň, o kterou je sesilatel výš, než vlastník lámaného kouzla. Magie potřebná na zlomení je o 6 magů vyšší, než li byla potřebná k seslání. Nikdy neví kolik má vložit únavy a PJovi musí sdělit kolik únavy je ochoten do kouzla vložit.' WHERE id = 731 AND nazev = 'Zlom kouzlo';
UPDATE kouzla SET rozsah = 'kruh o poloměru 20 sáhů', popis = 'Únava: 1 bod za směnu. Po seslání se rozzáří všechny posedlé předměty, či osoby. Posednutí se myslí démonem. svítí intenzitou pochodně, i když se pak vzdálí z dosahu kouzla. Ukáží se i pokud jsou požehnáni temným bohem či entitou, která je všeobecně (či sesilatelem) vnímána jako zlá.' WHERE id = 732 AND nazev = 'Najdi zlo';
UPDATE kouzla SET rozsah = 'kruh o poloměru 20 sáhů', popis = 'Únava: 1 bod za směnu. Po seslání se rozzáří všechny požehnané předměty, či osoby. Požehnání se myslí andělem. svítí intenzitou pochodně, i když se pak vzdálí z dosahu kouzla. Ukáží se i pokud jsou požehnáni bohem či entitou světla, která je všeobecně (či sesilatelem) vnímána jako dobrá.' WHERE id = 733 AND nazev = 'Najdi dobro';
UPDATE kouzla SET rozsah = 'kruh o poloměru dosahu', popis = 'Únava: 1 bod. Zviditelní všechny neviditelné předměty a postavy, ale pouze pro novice, které jsou, či vstoupí do oblasti pod vlivem kouzla. Nepůsobí na ty, kteří jsou neviditelní od ´´přírody´´.' WHERE id = 734 AND nazev = 'Najdi neviditelnost';
UPDATE kouzla SET rozsah = '1 cíl', popis = 'Novic si speciálním dotykem označí cíl. Ať již předmět osobu či místo. Takto označený cíl bude vždy cítit, až do vzdálenosti 70 sáhů. Za každý sáh dřeva se dosah sníží o 5 sáhů. Za každý sáh kamene se dosah sníží o 10 sáhů. Za každý coul železa se dosah sníží o 15 sáhů. Bude vědět směr a vzdálenost kde cíl je. Značku je možné skrýt skrze kouzlo nevycítitelnost. Novic může mít aktivních tolik značek, kolik je jeho úroveň.' WHERE id = 735 AND nazev = 'Tajná značka';
